-- Script: 036-reabastecimiento-automatico.sql
-- Módulo: 30 - ReabastecimientoAutomatico
-- Responsable: Maxi

CREATE TABLE "ReglasReabastecimiento" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "ProductoId" integer NOT NULL,
    "AlmacenId" integer NOT NULL,
    "ProveedorPreferidoId" integer,
    "StockActual" integer NOT NULL,
    "StockMinimo" integer NOT NULL,
    "PuntoReorden" integer NOT NULL,
    "StockMaximo" integer NOT NULL,
    "CantidadLoteCompra" integer NOT NULL,
    "Activa" boolean NOT NULL,
    "UltimaEvaluacion" timestamp with time zone,
    "Observaciones" character varying(500),
    CONSTRAINT "PK_ReglasReabastecimiento" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_ReglasReabastecimiento_StockActual" CHECK ("StockActual" >= 0),
    CONSTRAINT "CK_ReglasReabastecimiento_StockMinimo" CHECK ("StockMinimo" >= 0),
    CONSTRAINT "CK_ReglasReabastecimiento_PuntoReorden" CHECK ("PuntoReorden" >= "StockMinimo"),
    CONSTRAINT "CK_ReglasReabastecimiento_StockMaximo" CHECK ("StockMaximo" > "PuntoReorden"),
    CONSTRAINT "CK_ReglasReabastecimiento_CantidadLoteCompra" CHECK ("CantidadLoteCompra" >= 1),
    CONSTRAINT "FK_ReglasReabastecimiento_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ReglasReabastecimiento_Almacenes_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacenes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ReglasReabastecimiento_Proveedores_ProveedorPreferidoId" FOREIGN KEY ("ProveedorPreferidoId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_ReglasReabastecimiento_Codigo" ON "ReglasReabastecimiento" ("Codigo");
CREATE UNIQUE INDEX "IX_ReglasReabastecimiento_Codigo_Normalizado" ON "ReglasReabastecimiento" (lower(btrim("Codigo")));
CREATE UNIQUE INDEX "IX_ReglasReabastecimiento_ProductoId_AlmacenId" ON "ReglasReabastecimiento" ("ProductoId", "AlmacenId");
CREATE INDEX "IX_ReglasReabastecimiento_AlmacenId" ON "ReglasReabastecimiento" ("AlmacenId");
CREATE INDEX "IX_ReglasReabastecimiento_ProveedorPreferidoId" ON "ReglasReabastecimiento" ("ProveedorPreferidoId");
CREATE INDEX "IX_ReglasReabastecimiento_Activa" ON "ReglasReabastecimiento" ("Activa");

CREATE TABLE "EjecucionesReabastecimiento" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ReglaReabastecimientoId" integer NOT NULL,
    "FechaEjecucion" timestamp with time zone NOT NULL,
    "StockActual" integer NOT NULL,
    "CantidadSugerida" integer NOT NULL,
    "Estado" character varying(25) NOT NULL,
    "SolicitudCompraId" integer,
    "Observacion" character varying(300),
    CONSTRAINT "PK_EjecucionesReabastecimiento" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_EjecucionesReabastecimiento_StockActual" CHECK ("StockActual" >= 0),
    CONSTRAINT "CK_EjecucionesReabastecimiento_CantidadSugerida" CHECK ("CantidadSugerida" >= 1),
    CONSTRAINT "CK_EjecucionesReabastecimiento_Estado" CHECK ("Estado" IN ('Pendiente', 'SolicitudGenerada', 'Descartada')),
    CONSTRAINT "FK_EjecucionesReabastecimiento_Reglas_ReglaReabastecimientoId" FOREIGN KEY ("ReglaReabastecimientoId") REFERENCES "ReglasReabastecimiento" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_EjecucionesReabastecimiento_Solicitudes_SolicitudCompraId" FOREIGN KEY ("SolicitudCompraId") REFERENCES "SolicitudesCompra" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_EjecucionesReabastecimiento_ReglaReabastecimientoId" ON "EjecucionesReabastecimiento" ("ReglaReabastecimientoId");
CREATE INDEX "IX_EjecucionesReabastecimiento_SolicitudCompraId" ON "EjecucionesReabastecimiento" ("SolicitudCompraId");
CREATE INDEX "IX_EjecucionesReabastecimiento_Estado" ON "EjecucionesReabastecimiento" ("Estado");
CREATE INDEX "IX_EjecucionesReabastecimiento_FechaEjecucion" ON "EjecucionesReabastecimiento" ("FechaEjecucion");
